INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014078', 'AN1558', 'グンナル', 'He is Ragnar''s Brother.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156517-cafNAxFz1QAx.png', NULL, NULL, '最上嗣生', NULL, 156517, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
