INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014080', 'AN1558', 'エストリッド', 'Daughter of King Sweyn and sister to Harald and Canute.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300483-A3nuRvonzUzx.jpg', NULL, NULL, '赤﨑千夏', NULL, 300483, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
