INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014178', 'AN1564', 'Pascal', 'Type: Machine Lifeform  A Machine Lifeform with a soft demeanor and gentle personality who is disconnected from the Machine Network that binds all Machine Lifeforms. Extensively knowledgeable, he created his own community where he lives with other like-minded Machine Lifeforms.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138307-3qE8YX8kW63R.png', NULL, NULL, '悠木碧', 250, 138307, 'SUPPORTING', 149) ON CONFLICT DO NOTHING;
