INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014277', 'AN1569', 'ヒタチ・千草', 'Race: Human Affiliation: Takemikazuchi Familia Level: 2  Chigusa Hitachi is a member of the Takemikazuchi Familia. Despite having a timid and shy personality, she is loyal to her Familia, especially Ouka who she has feelings for.', 16, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142553-qRChPxIz6UUr.jpg', NULL, NULL, '井口裕香', 154, 142553, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014278', 'AN1569', 'アイズ・ヴァレンシュタイン', 'Ais Wallenstein, also known as the Sword Princess, is a First-Class Adventurer and a key member of the Loki Familia. Among the small fraction of First-Class Adventurers, she is considered one of the strongest.', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b87655-7QjpIyyZuqyp.png', NULL, NULL, '大西沙織', 162, 87655, 'SUPPORTING', 5651) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014279', 'AN1569', 'レット', 'Race: Xenos Affiliation: Xenos '' Ouranos Level: 4 (estimate)  Let is a Goblin Xenos. As a Xenos, Let is far more intelligent and powerful than a normal monster.  Let refers to Bell as Mister. Bell mentions that he tries to act like a gentleman. He is shown to have rational thinking as he was one of the few Xenos who did not wanted to attack other adventurers after knowing that Ranye’s group was killed by the Ikelos Familia.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209698-zV1svycBpaew.png', NULL, NULL, '竹田海渡', NULL, 209698, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014280', 'AN1569', 'アミッド・テアサナーレ', 'A member of the Dian Cecht Familia.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b183118-H78SZhiR84Gd.png', NULL, NULL, '加隈亜衣', NULL, 183118, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014281', 'AN1570', 'セイカ・ランプローグ', 'He is the reincarnation of Haruyoshi Kuga. He is very kind and will do anything to protect people dearest to him.', 7, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283420-eVEVM2zISWMb.png', NULL, NULL, '花守ゆみり', NULL, 283420, 'MAIN', 159) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014282', 'AN1570', 'イーファ', 'A young girl who served as a slave in Seika''s birthplace, the House of Count Lambrogue. Although she hides it from her surroundings, she has the power to see "spirits" that even Seika cannot see, and the talent to follow them. Ever since she was young, she has taken a liking to Seika, who has treated her well.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283421-WO7ONF9G0bj6.png', NULL, NULL, '和氣あず未', NULL, 283421, 'MAIN', 149) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014283', 'AN1570', 'アミュ', 'A commoner girl who, like Seika, came to take the entrance exam for Rodnaire Academy of Magic. She has magical aptitude for all attributes, and she has an amazing talent for swords and magic, topping the entrance exam. Because of her ability, it is rumored that she is a "hero" who can defeat the Demon King.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283422-sQeTzokEtyZt.png', NULL, NULL, '稗田寧々', NULL, 283422, 'MAIN', 115) ON CONFLICT DO NOTHING;
