INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH014371', 'AN1574', 'マルクス', 'Markus or Marx is a member of the guild Flame Emperors along side Mii, Misery, and Shin. Marx is a trap specialist and tends to uses different traps and spells to his advantage but tends to doubt himself.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b158416-zeNcJmCQ8leO.png', NULL, NULL, '石田彰', NULL, 158416, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
