INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015079', 'AN1608', '期聖', 'Race: Human Age: Unknown Tao Attribute: Unknown Occupation: Asaemon Affiliation: Yamada Clan Rank: 11th  Kishou is the 11th rank Asaemon in the Yamada Clan and was assigned to keep watch over the criminal, Warped Keiun.  Kishou is an individual who is known for never losing his composure and rarely acting assertive. He is able to see the big picture in situations and finds it annoying when people question his way of handling them. Kishou has shown that he doesn''t mind taking the easy way out, of', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b151777-wY3ktSkeiwe3.jpg', NULL, NULL, '土岐隼一', NULL, 151777, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
