INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015153', 'AN1611', '技術部長', NULL, 56, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b350661-4O2xwymsUop5.png', NULL, NULL, '志賀麻登佳', NULL, 350661, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015154', 'AN1612', '木之下茜', 'Akane is a college student who had just broken up with her ex-boyfriend. Mainly because of him falling in love with another female gamer he met in the game Forest Of Savior (FOS). She is also a player of the said game and is a part of the guild named [Chocolate Rabbit]. Her character''s name is Akane and her character''s role is a Paladin. She is not tech savvy but she really likes playing the game and getting along with everyone.', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197172-MfY8D8sSMjHy.png', '5月9日', NULL, '水瀬いのり', NULL, 197172, 'MAIN', 1829) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015155', 'AN1612', '山田秋斗', 'Yamada is a high school student who is an intellectual and a good looking guy. He is not interested in romance but in playing games. He is a famous pro-gamer and receives money from sponsors. He mainly plays FPS (First Person Shooter) games. He is a player of the game Forest Of Savior (FOS) and a part of a guild named [Chocolate Rabbit]. His character''s name is Yamada and his character''s role is a Wizard.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b197173-t2KNplNgpQV6.png', '9月21日', NULL, '内山昂輝', NULL, 197173, 'MAIN', 2390) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015156', 'AN1612', 'えり', 'Takuma''s current girlfriend.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302089-D85KHdRf08mz.png', NULL, NULL, '山根綺', NULL, 302089, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015157', 'AN1612', '佐々木瑛太', 'Sasaki is the older brother of Runa Sasaki. He is also Yamada-kun''s senpai back in their hometown. His hobby is playing video games. He also plays the game Forest of Savior (FOS) and is also a member of the guild [Chocolate Rabbit].', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199121-8PgP309K6DkU.png', '6月11日', NULL, '花江夏樹', NULL, 199121, 'SUPPORTING', 463) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015158', 'AN1612', '佐々木瑠奈', 'Runa is a middle high school student who usually dresses in Lolita Fashion. She is the younger sister of Eita Sasaki. She is also being mentored by Yamada during the weekends. She is also a player of the game Forest Of Savior (FOS) and a member of the guild [Chocolate Rabbit].', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b199120-cC3hg83DYcto.png', NULL, NULL, '加隈亜衣', NULL, 199120, 'SUPPORTING', 222) ON CONFLICT DO NOTHING;
