INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015491', 'AN1627', 'リンデル', 'Elias'' magician master, commonly referred to as Lindel, who lives in the Land of Dragons. His title is Echoes, Song of Flowers.  (Source: MAL)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n129384-zSLY3QNgirXd.png', NULL, NULL, '浪川大輔', NULL, 129384, 'SUPPORTING', 242) ON CONFLICT DO NOTHING;
