INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015519', 'AN1628', 'リーン', 'As head of the Fairy Tribe of Mismede, Leen serves as the court mage of the Kingdom of Mismede and is capable of using her personal null magic, ''Program''. Over the span of 200 years, she has used ''Program'' to create an automated teddy bear named Paula who can to interact with humans, though it has yet to gain the capability to speak.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b122737-4WSV7nfAo7Ff.png', NULL, NULL, '上坂すみれ', NULL, 122737, 'SUPPORTING', 186) ON CONFLICT DO NOTHING;
