INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015523', 'AN1628', 'スゥシィ・エルネア・オルトリンデ', 'Daughter of Duke Alfred Urnes Ortlinde, and Yumina''s cousin. Sushie prefers for her friends to call her Sue.  Touya''s sixth fiancée.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/122736-UM0vGqHMmL16.jpg', NULL, NULL, '山下七海', NULL, 122736, 'SUPPORTING', 122) ON CONFLICT DO NOTHING;
