INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015527', 'AN1628', '琥珀', 'Kohaku, formerly known as The White Tiger, is a companion and contracted beast of Touya on his journey. She is one of the Four Heavenly Beasts and also the leader of the Magical Beasts.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/122738-DrBpEouL0wpV.jpg', NULL, NULL, '甲斐田ゆき', NULL, 122738, 'SUPPORTING', 129) ON CONFLICT DO NOTHING;
