INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015596', 'AN1633', 'ティガー・ヒルデブラント', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b308400-nyLSEuOiSaO0.jpg', NULL, NULL, '杉田智和', NULL, 308400, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015597', 'AN1634', 'スレッタ・マーキュリー', 'A second-year student in the piloting department, who transferred to the school from Mercury. Suletta is timid and somewhat lacks communication skills. She is the pilot of the Gundam Aerial developed on Mercury.', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279507-nKzMuTa8fBek.png', NULL, NULL, '市ノ瀬加那', NULL, 279507, 'MAIN', 1254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015598', 'AN1634', 'ミオリネ・レンブラン', 'An attractive and academically distinguished second-year student in the management strategy department. Miorine is the only daughter of Delling Rembran, the president of the Beneritt Group and chairman of the school''s board. She has a strong rebellious feeling towards her father.  Miorine has shown an interest in gardening in her spare time, with an apparent focus on tomatoes.  (Source:  Mobile Suit Gundam: The Witch from Mercury Official Site)', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279508-JvHoPuV6NwOs.jpg', NULL, NULL, 'Lynn', NULL, 279508, 'MAIN', 903) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015599', 'AN1634', 'ヌーノ・カルガン', 'He is a second-year mechanic in the Earth dormitory. He is a geek who is well versed in software, and he and Ojero work together as partners in crime.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290041-7XKIsBbQeZVv.jpg', NULL, NULL, '畠中祐', NULL, 290041, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015600', 'AN1634', 'アリヤ・マフヴァーシュ', 'A third-year mechanic in the Earth Dormitory. She is a sensible person who keeps her own pace. She loves fortune-telling and livestock (yaks, goats, and chickens), which she brought from her hometown.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290044-wCC5Ejctm8Nq.jpg', NULL, NULL, '島袋美由利', NULL, 290044, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015601', 'AN1634', 'レネ・コスタ', 'A second-year pilot student in the Grassley House. She is one of the female students who support Shaddiq. She seems to be a friendly person, but she is a black-hearted person who changes her demeanor when it comes to male and female students.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294367-3BTOxIR2DmaF.png', NULL, NULL, '鈴代紗弓', NULL, 294367, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015602', 'AN1634', 'グストン・パーチェ', 'A spaceship pilot who works with the smuggler Feng Jun.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294673-1UngKPTB8dyI.png', NULL, NULL, '柳田淳一', NULL, 294673, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015603', 'AN1634', 'ネボラ', 'One of the four co-CEOs who manage Peil Technologies (one of the Benerit Group''s three branches) via a parliamentary system.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288847-hFKwhtJpLKoV.png', NULL, NULL, '沢海陽子', NULL, 288847, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015604', 'AN1634', 'ニューゲン', 'One of the four co-CEOs who manage Peil Technologies, one of the Benerit Group''s three branches, via a parliamentary system.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288839-K69vwlNnDFG9.png', NULL, NULL, '勝生真沙子', NULL, 288839, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015605', 'AN1634', 'エナオ・ジャズ', 'A third-year pilot student in the Grassley dormitory. She is one of the female students who supports Shaddiq. She is a mysterious type who quietly uses her sixth sense.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294366-qRESJWHFN8jP.png', NULL, NULL, '若山詩音', NULL, 294366, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015606', 'AN1634', 'フェルシー・ロロ', 'She is a second-year pilot in the Jeturk House. The type of person who is a reckless, headstrong pilot. She respects Guel as a pilot.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288848-RPct6e1DL2SD.png', NULL, NULL, '高田憂希', NULL, 288848, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015607', 'AN1634', 'ベルメリア・ウィンストン', 'As a researcher at Peil Technologies, she is involved with the development of the Gundam Pharact.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294672-mmhK6WkA5ONN.png', NULL, NULL, '恒松あゆみ', NULL, 294672, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015608', 'AN1634', 'ゴルネリ', 'One of the four co-CEOs who manage Peil Technologies (one of the Benerit Group''s three branches) via a parliamentary system.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288845-HkfzHkTrcGd4.png', NULL, NULL, '斉藤貴美子', NULL, 288845, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015609', 'AN1634', 'グエル・ジェターク', 'An heir to Jeturk Heavy Machinery, one of the group''s three branches, and a third-year student in the piloting department. Guel has a rough temperament and is quick to anger. As the ace pilot of Jeturk House, he has absolute confidence in his own skills.  (Source: Official Website)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279506-pZUmhduBLIzf.png', NULL, NULL, '阿座上洋平', NULL, 279506, 'SUPPORTING', 462) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015610', 'AN1634', 'リリッケ・カドカ・リパティ', 'She is a first-year student in the Business Strategy Department, living in the Earth Dormitory. She is cheerful and friendly. She loves to talk about her love life and is popular among male students.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290042-BiWwUrbzG2I4.jpg', NULL, NULL, '稲垣好', NULL, 290042, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015611', 'AN1634', 'サビーナ・ファルディン', 'She is a third-year pilot at the Grassley House. She is a talented woman who assists Shaddiq in his work in and out of the school as his second in command.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294370-7U2JzbMcF72D.png', NULL, NULL, '瀬戸麻沙美', NULL, 294370, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015612', 'AN1634', 'ロウジ・チャンテ', 'A first-year mechanic in the Burion House. He belongs to the Dueling Committee. He is familiar with mobile crafts and other mecha, and always carries his own modified Haro.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288841-DAhM8RMhLKzf.png', NULL, NULL, '佐藤元', NULL, 288841, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015613', 'AN1634', 'ナジ・ゲオル・ヒジャ', 'The leader of the Dawn of Fold, an anti-Spacian organization active on Earth. He carries out guerilla activities in the name of improving the position of Earth''s inhabitants.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307149-9s5NSeT7VwF4.jpg', NULL, NULL, '楠大典', NULL, 307149, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015614', 'AN1634', 'ナイラ・バートラン', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282620-nJl5pJEzKIso.png', NULL, NULL, '小島幸子', NULL, 282620, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015615', 'AN1634', 'エラン・ケレス', 'The top pilot backed by Peil Technologies, one of the group''s three branches. A third-year student in the piloting department. Elan is a taciturn and solitary person, who doesn''t open his heart to anyone in school. He has an interest to Suletta.  (Source: Official Website)', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b279505-4JNsemle78MV.jpg', NULL, NULL, '花江夏樹', NULL, 279505, 'SUPPORTING', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015616', 'AN1634', 'ソフィ・プロネ', 'Sophie is a sadistic and aggressive girl. She is excitable and impulsive, and appears to enjoy fighting and threatening her enemies.  She is easily excitable in combat, Sophie also has an interest in fellow witches and Gundams like Suletta and the Aerial, both of whom she had watched through videos of their duels, and was in euphoric delight at fighting both, developing an obsession towards both.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296137-sUlCCN8WdcqU.png', NULL, NULL, '井澤詩織', NULL, 296137, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015617', 'AN1634', 'プロスペラ・マーキュリー', 'The CEO of the Shin Sei Development Corporation, which is headquartered at Mercury. She was in charge of the Gundam Aerial''s development, and is Suletta''s mother. She always wears special headgear for physical support.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289107-U2GQBQ7dfk6H.jpg', NULL, NULL, '能登麻美子', NULL, 289107, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015618', 'AN1634', 'シーシア', 'A girl who lives in a designated recovery plan area on Earth. She worries about her father, who joined the Dawn of Fold and went to the front lines.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307150-D0TmO6RY1uVD.jpg', NULL, NULL, '川井田夏海', NULL, 307150, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015619', 'AN1634', 'カルド・ナボ', 'She was a researcher who represented the Vanadis Institute. As a leading proponent of the "GUND FORMAT" theory, she had earned the respect of her fellow researchers', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282618-Q72gXY9X2HXH.png', NULL, NULL, '一城みゆ希', NULL, 282618, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015620', 'AN1634', 'チュアチュリー・パンランチ', 'Chuchu is a troubled young girl, who is an Earthian facing discrimination from a significant portion of the Spacians who look down on Earthians as underlings. Being in the same school as many Spacians, she along with her Earthian friends has been the subject of regular abuse and harassment. This along with her home people being the subject of Spacian oppression and exploitation has given Chuchu a profoundly negative impression of all Spacians often deriding them as "Shitty Spacians" and lashing ', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286806-rVT7XqzCOGLO.png', NULL, NULL, '富田美憂', NULL, 286806, 'SUPPORTING', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015621', 'AN1634', 'デリング・レンブラン', 'The president of the Benerit Group, and supervising representative of the auditing organization Cathedra.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288842-PIWMS5h3zYTi.png', NULL, NULL, '内田直哉', NULL, 288842, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015622', 'AN1634', 'ペトラ・イッタ', 'She is a second-year mechanic student in the Jeturk House. She is the cool, intelligent, honor student type. Much like Felsi, she adores Guel.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288849-rWsIbEfBpfrv.png', NULL, NULL, '広瀬ゆうき', NULL, 288849, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015623', 'AN1634', 'ラウダ・ニール', 'Lauda Neill is in his third year of the pilot program. He is the deputy head of the Jeturk House. He is a half-brother to Guel, and although they are in the same grade, he is the younger brother. Unlike his older brother, he is calm and rational.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b288843-9dI2Ee24QOIW.png', NULL, NULL, '大塚剛央', NULL, 288843, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015624', 'AN1634', 'ケナンジ・アベリー', 'A commander in the Dominicus special forces. 21 years earlier, Kenanji served as a Begir-Beu pilot during the Vanadis Incident.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307151-ckcgtfmvSYsa.jpg', NULL, NULL, '上田燿司', NULL, 307151, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015625', 'AN1634', 'ナディム・サマヤ', 'The father of the Samaya family.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282621-X6RRGOWOKrGm.png', NULL, NULL, '土田大', NULL, 282621, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015626', 'AN1634', 'ニカ・ナナウラ', 'A second-year student in the mechanical department, who belongs to Earth House. She loves mecha and is very curious about Suletta''s Gundam Aerial. Nika has outstanding maintenance skills and is proud of herself for customizing Chuchu''s Demi Trainer.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b286805-tJgk5G8l4c1H.png', NULL, NULL, '宮本侑芽', NULL, 286805, 'SUPPORTING', 83) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015627', 'AN1634', 'オジェロ・ギャベル', 'He is a second-year mechanic student in the earth dormitory. He is a mood-maker with a cheerful personality. A gambler who spends the dormitory''s living expenses on dueling games.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290040-bjNNpfV3rfyn.jpg', NULL, NULL, 'KENN', NULL, 290040, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015628', 'AN1634', 'マルタン・アップモント', 'He is the head of the Earth Dormitory and a third-year student in the Department of Business Strategy. He is an indecisive and somewhat unreliable leader. He has a hard time dealing with the dorm members who have strong personalities.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290039-wZDPBmuTHuDP.png', NULL, NULL, '榎木淳弥', NULL, 290039, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015629', 'AN1634', 'エリクト・サマヤ', 'A four-year-old girl who lives with her family at Fólkvangr. She is the daughter of Elnora and Nadim. Ericht is an innocent child, and so curious that her parents sometimes don''t know what to do with her.', 4, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b304462-hSgSxVT1Npro.png', NULL, NULL, '市ノ瀬加那', NULL, 304462, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015630', 'AN1634', 'オルコット', 'A mobile suit team commander from the anti-Spacian organization Dawn of Fold. He is a veteran warrior who is trusted by his forces.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b307152-xlOv5nDT7Vi3.jpg', NULL, NULL, '三上哲', NULL, 307152, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
