INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015632', 'AN1634', 'シャディク・ゼネリ', 'An adopted child of the CEO of Grassley Defense Systems, one of the group''s three branches. A third-year student in the piloting department who leads Grassley House. Although still a student Shaddiq has shown his skill in business too, he is a candidate for next generation executive.  (Source: Official Website)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279509-UnPozXRtNYwy.jpg', NULL, NULL, '古川慎', NULL, 279509, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015633', 'AN1634', 'メイジー・メイ', 'A second-year pilot student in the Grassley House.She is an overwhelmingly positive thinker who spreads smiles to those around her.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294368-cAtwVshgU4IU.png', NULL, NULL, '貫井柚佳', NULL, 294368, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015634', 'AN1634', 'イリーシャ・プラノ', 'A second-year pilot student in the Grassley House. Another of the female students who support Shaddiq. She is timid, lacks self-confidence, and is a worrywart. She is good friends with Maisie.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b294369-IbO8lm93I58d.png', NULL, NULL, '前川涼子', NULL, 294369, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
