INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015637', 'AN1634', 'カル', 'One of the four co-CEOs who manage Peil Technologies (one of the Benerit Group''s three branches) via a parliamentary system.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b288846-W6saUNwW4OcV.png', NULL, NULL, '小宮和枝', NULL, 288846, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015638', 'AN1634', 'ノレア・デュノク', 'Norea is an Earthian who got involved with the Anti-Spacian terrorist group Dawn of Fold. She was trained as a Gundam pilot along with Sophie.  Norea presents herself as a calm and level-headed person, often maintaining a flat demeanor in conversations. She is often quick to remind others, especially Sophie, to stay focused on their main objectives. However, she harbors a very deep-seated hatred of the Spacians for abandoning the Earth, which also includes other Earthians who left the planet. Sh', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b296138-GksOwpRBrBQI.png', NULL, NULL, '悠木碧', NULL, 296138, 'SUPPORTING', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015639', 'AN1634', 'ティル・ネイス', 'He is a third-year mechanic in the Earth Dormitory. He is taciturn and calm. One of the most important members of the dormitory, he is a pillar of support for the other dormitory members.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290043-XfY78n2fl1rc.jpg', NULL, NULL, '天崎滉平', NULL, 290043, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
