INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015960', 'AN1646', 'イヴ', 'Eve is the main protagonist of the BIRDIE WING: Golf Girls'' Story series. She is a survivor who made a living by betting on golf. Her struggling past resulted in a rough and powerful playing style.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253820-yVhieWvjxZNO.png', NULL, NULL, '鬼頭明里', NULL, 253820, 'MAIN', 247) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015961', 'AN1646', '天鷲葵', 'Aoi Amawashi is the daughter of the Tenwashi Group, one of the largest corporations in the world, and a thoroughbred in the golf world. Being the ace of the prestigious Raijin Girls’ Academy golf club, Aoi became known as the "Innocent Tyrant" as she enjoys golf and defeats her opponents with a sweet and innocent smile', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253819-ui4XCjXVnag3.png', NULL, NULL, '瀬戸麻沙美', NULL, 253819, 'MAIN', 135) ON CONFLICT DO NOTHING;
