INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH015964', 'AN1646', '亜室麗矢', 'Reiya Amuro is the head coach of the golf team at Raijin Girls’ Academy. A former professional golfer who''s pro career was cut short, Reiya manages the golf team and acts as Aoi''s mentor as she progresses in her own pro career. He also brings Eve onto the team and teaches her to a degree.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258745-x10WDg0SecTw.png', NULL, NULL, '古谷徹', NULL, 258745, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
