INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016516', 'AN1676', '輪堂鴉夜', 'A young Heian era woman and a yōkai, who is beheaded by an unknown half-demon assailant from Britain and has her headless body taken away. Since she is a demon, she cannot die (though being decapitated by a half-demon means she cannot heal herself) and thus her head continues to live on, ultimately seeking support from Tsugaru to search the assailant and take revenge.', 962, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301052-dCPTkqyRenCn.png', NULL, NULL, '黒沢ともよ', NULL, 301052, 'MAIN', 279) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH016517', 'AN1676', '真打津軽', 'A former member of a special oni extermination squad charged with slaughtering monsters across Japan during the Meiji Restoration. At some point, he was injected with oni blood by the same man who beheaded Aya and turned into a half-oni himself. Though the power allows him to kill oni and other supernatural beings with his bare hands, he knows that at some point in the future the oni blood will overcome his human personality and he will be put down by a similar hunter. In the meantime, he suppor', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301053-cBSSf5rlEO5B.jpg', NULL, NULL, '八代拓', NULL, 301053, 'MAIN', 480) ON CONFLICT DO NOTHING;
