INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017025', 'AN1710', '受付嬢', 'A young woman who runs the Guild''s front office as a receptionist and hands out contracts to adventurers. She shows concern over the villages pleading for help against the goblins and is exasperated from how few experienced adventurers would take such jobs. This problem would leave inexperienced rookies to die from them or worse. She holds great amounts of respect for Goblin Slayer, due to his willingness to take on many goblin contracts others would not touch.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/126485-2zo57ux4EMeC.jpg', NULL, NULL, '内田真礼', NULL, 126485, 'SUPPORTING', 551) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017026', 'AN1710', '蟲人僧侶', 'He is one of the six gold-ranked adventurers renowned for defeating the Demon Lord ten years ago.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136314-WIEX7DNvv8rp.png', NULL, NULL, '武内駿輔', NULL, 136314, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017027', 'AN1710', '魔女', 'Witch is a silver ranked adventurer who is in a party with Spearman. She is a beautiful spell-caster with long, purple hair who wears a revealing set of robes, dark colored with gold yellow outlining. She is usually shown as being rather seductive, acting in a rather amorous manner, often suggesting sexual undertones in otherwise normal conversation, which causes those she interacts with to become flustered or embarrassed. Despite her teasing, she is shown to be caring of those around her, offer', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n126486-e0DjNT3rBOT7.png', NULL, NULL, '日笠陽子', NULL, 126486, 'SUPPORTING', 459) ON CONFLICT DO NOTHING;
