INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017152', 'AN1718', 'フィン・フェネック', 'The locked room instructor at BLUE and the world''s expert on locked room studies.  She is one of the few people in the world who holds a S-rank detective license. With her "Phoenix touch" ability, she has found 5,000 hidden rooms, 3,000 illegal constructions, and 10,000 tricks of physics so far.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316428-2jNKTh2nsUwW.png', NULL, NULL, '潘めぐみ', NULL, 316428, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
