INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017228', 'AN1721', 'アリウス・サバラモンド', 'Lord Arius Sabaramond, the "Shiranui Sky Tower", is the former first-ranked Imperial Court Sorcerer of the Byandy Empire.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b255866-HQORfD8ILK2q.png', NULL, NULL, '村瀬歩', NULL, 255866, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017229', 'AN1721', 'フラムロディア・バャディラーズ', 'Framrodia Byandiraz was the last emperor of the Byandy Empire, his reign and empire concomitantly ending when he was assassinated by Corpse God, the fourth of rank among his imperial sorcerers and his closest friend. He and several members of his court remain Corpse God''s friends in death as souls who are bound to him via necromancy.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b302219-SUli5JBJYPA1.png', NULL, NULL, '田村睦心', NULL, 302219, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017230', 'AN1721', 'ウルドヴィジア', 'Urdwigia is a thunder dragon, who became the right arm of Xiaoyu Lei.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b302210-aK3xr2FNReSA.png', NULL, NULL, '伊瀬茉莉也', NULL, 302210, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
