INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017283', 'AN1726', 'コリンナ', 'A very experienced alchemist in charge of making potions for Klausner''s Domain. She shows Sei the only known diary of a previous Saint to help her learn how to activate and use her "Saint''s Magic". She frequently admonishes Leo, her grandson, for his blunt manner of speaking and lack of tact.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b245650-9epTVJOlLdWF.png', NULL, NULL, '小山茉美', NULL, 245650, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
