INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017297', 'AN1727', 'ミト', 'The remnants of a demon''s power found lingering in the forest. He takes on the form of a child and clings to the residents of Belgrieve''s house. Though unexpressive, he is quite curious.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b322630-aort4bLjMPGP.png', NULL, NULL, '長縄まりあ', NULL, 322630, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017298', 'AN1727', 'ヘルベチカ・ボルドー', 'Countess of the Bordeaux region, and the eldest of the sisters.  Though gifted in her own right, she tends to lose herself when talented people are around.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b312114-q7OndkFny7I4.png', NULL, NULL, '井上麻里奈', NULL, 312114, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
