INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017415', 'AN1736', '上原メイ子', 'Alcoholsoft''s chief illustrator who is extremely skilled. She has a gentle personality.   In the anime, she is the first person at Alcoholsoft to accept Konoha and worries about her when she disappears.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313988-PdURTRF7WPts.png', NULL, NULL, '堀江由衣', NULL, 313988, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017416', 'AN1736', '下田かおり', 'Artist and planner at Alcoholsoft with a trademark cat-eared hat. She has a gentle personality and a deep passion for Bishoujo games. She has a level-headed view of the company, but in the anime, Konoha''s situation weighs on her mind.', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313989-K0IFCWzXro7Q.png', NULL, NULL, '川澄綾子', NULL, 313989, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
