INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017465', 'AN1739', '白崎優清', 'He is the chief of the Planning and Sales department at Minette whose concentration at work is high and his performance is good. In matters outside of work, he gets easily distracted and often makes mistakes.', 33, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b305653-fmenHf6rPHZd.png', '2月22日', 'AB', '梅原裕一郎', 181, 305653, 'MAIN', 278) ON CONFLICT DO NOTHING;
