INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017557', 'AN1748', '青藤マサキ', 'The protagonist in the fifth season, FLCL Shoegaze. He is a high school student who can see ghosts all around him.', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320310-eMBNLzNArwo8.jpg', NULL, NULL, '千葉翔也', NULL, 320310, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017558', 'AN1748', 'Harumi Araishu', 'The 15-year-old protagonist of season five, FLCL Shoegaze. She is a high school student who befriends Masaki Aofuji and helps him investigate the tower.', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b320311-UPsKmMxo9r2o.jpg', NULL, NULL, '天野聡美', NULL, 320311, 'MAIN', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017559', 'AN1748', '河本カナ', 'The 17-year-old protagonist of season three, FLCL Alternative. She is a noisy airhead who works part time at a restaurant and hangs with her friends, Mossan, Hijiri and Pets in what was a unremarkable time until she crossed paths with Haruko who opened her N.O. Channel.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131264-IvhuKENyZnwe.png', NULL, NULL, '美山加恋', NULL, 131264, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017560', 'AN1748', '神田束太', 'A member of the Department of Interstellar Immigration who bares a resemblance to Naota, being one of Haruko''s previous targets before she deemed his N.O Channel too.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131265-dZ2qeiyVrN3w.png', NULL, NULL, '青山穣', NULL, 131265, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
