INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017570', 'AN1749', '音無小鳥', 'The secretary of 765 Production, Kotori is open-minded and smart, but also sometimes shy.  Due to her position in the agency, at slow hours she can often doze off or start to daydream about outrageous things. She also spends much of her free time during workdays browsing 2chan, and because of this she is often thought of as being a pervert. Despite not being an idol herself, Kotori loves to sing. While Kotori''s exact age has never been revealed, we know that Kotori is a little older than Azusa (', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b43706-BQQiUgL8aPu6.png', '9月9日', 'AB', '滝田樹里', 159, 43706, 'SUPPORTING', 64) ON CONFLICT DO NOTHING;
