INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017657', 'AN1752', '三杉淳', 'Date of birth: 23rd June  National Team Jersey Number: #14  Position: Defender / Part-time coach  Nickname: Field no Kikoshi (Field Prince), Ace of Glass Special Techniques: Drive shoot and Off-side strategy   Jun Misugi is easily one of Japan’s best players. Unfortunately, his failing heart condition forces him to play for only a short time almost every game. During Japan''s match against Argentina, Japan''s coach silently thought to himself that Jun would have been Japan''s top player (even bette', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b6781-EdvpOyUjuFLp.jpg', NULL, NULL, '斉藤壮馬', NULL, 6781, 'SUPPORTING', 70) ON CONFLICT DO NOTHING;
