INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017680', 'AN1752', '見上辰夫', 'Former goalkeeper of the Japanese national team, Genzo Wakabayashi''s coach, All Japan Jr. Youth''s coach First appearance in Captain Tsubasa chapter 1  Former goalkeeper of the Japanese national team. He is the personal coach of Wakabayashi. He was be the first to find out who Roberto really is. He made Wakabayashi follow a hellish training before his match against Nankatsu and Tsubasa. As Wakabayashi felt depressed after taking a goal, Mikami hit him and told him that he would stop coaching him.', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/62319.jpg', NULL, NULL, '西村知道', NULL, 62319, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
