INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017699', 'AN1752', '沢木昇', 'Noboru Sawaki is the forward of Meiwa Higashi middle school in the Saitama prefecture, and he also played for Meiwa FC. He wears the number 11 and 9 jerseys, respectively.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b261284-vLUW6asvBtjN.png', '9月17日', 'A', NULL, NULL, 261284, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
