INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017701', 'AN1752', 'アモロドミニク', 'Amoro is a French keeper from the France Jr. Youth squad.  Amoro first appeared in the Original manga. He wears the jersey #1.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334543-iDnYrDicBSEc.jpg', '6月27日', 'B', '小林大紀', NULL, 334543, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
