INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017703', 'AN1752', 'ジョバンニ コンティ', 'Conti is a midfielder. He wears the jersey #7. He is based on the italian player Bruno Conti. In the Italian localization of Captain Tsubasa: Rise of New Champions, his surname is translated as "Ponti", possibly to avoid confusion with said real-life player.  (Source: Captain Tsubasa Wiki)', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334547-89USGkOxXqZI.jpg', '9月14日', 'O', '小林大紀', NULL, 334547, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017704', 'AN1752', 'ディーン', 'Dean is an English forward. He was a player of England Jr. Youth in J Boys'' Challenge.', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b334548-B27uYAdSGx4A.jpg', '9月12日', 'B', '濱岡敬祐', NULL, 334548, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
